from collections import deque

def shortest_path_grid(grid):
    R, C = len(grid), len(grid[0])
    if grid[0][0] != 0 or grid[R-1][C-1] != 0:
        return -1
    queue = deque([(0, 0, 1)])  # (r, c, distance)
    visited = {(0, 0)}
    while queue:
        r, c, dist = queue.popleft()
        if r == R - 1 and c == C - 1:
            return dist
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))
    return -1

grid = [[0, 0, 0], [1, 1, 0], [1, 1, 0]]
print(shortest_path_grid(grid))

from collections import deque

# Multi-source BFS: Distance to nearest 0 in matrix
def update_matrix(mat):
    R, C = len(mat), len(mat[0])
    dist = [[-1] * C for _ in range(R)]
    queue = deque()
    # Enqueue ALL sources (0s) simultaneously
    for r in range(R):
        for c in range(C):
            if mat[r][c] == 0:
                dist[r][c] = 0
                queue.append((r, c))
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                queue.append((nr, nc))
    return dist

